import type { ComboType } from "./types";

let audioCtx: AudioContext | null = null;
let masterBus: GainNode | null = null;
let soundEnabled = true;

export function isSoundEnabled(): boolean {
  return soundEnabled;
}

export function setSoundEnabled(enabled: boolean): void {
  soundEnabled = enabled;
}

function getContext(): { ctx: AudioContext; out: AudioNode } | null {
  if (!soundEnabled || typeof window === "undefined") return null;
  const Ctx =
    window.AudioContext ||
    (window as unknown as { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext;
  if (!Ctx) return null;
  if (!audioCtx) {
    audioCtx = new Ctx();
  }
  if (audioCtx.state === "suspended") {
    void audioCtx.resume().catch(() => {});
  }
  if (!masterBus && audioCtx) {
    // High-shelf presence boost (+5.5dB above 2.4kHz) + compressor for crisp, bright clarity
    const shelf = audioCtx.createBiquadFilter();
    shelf.type = "highshelf";
    shelf.frequency.value = 2400;
    shelf.gain.value = 5.5;

    const comp = audioCtx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.knee.value = 12;
    comp.ratio.value = 4;
    comp.attack.value = 0.002;
    comp.release.value = 0.12;

    masterBus = audioCtx.createGain();
    masterBus.gain.value = 0.95;

    masterBus.connect(shelf);
    shelf.connect(comp);
    comp.connect(audioCtx.destination);
  }
  return audioCtx && masterBus ? { ctx: audioCtx, out: masterBus } : null;
}

function makeDistortionCurve(amount = 40): Float32Array<ArrayBuffer> {
  const n = 8192;
  const curve = new Float32Array(new ArrayBuffer(n * 4));
  const k = amount;
  for (let i = 0; i < n; i++) {
    const x = (i * 2) / n - 1;
    curve[i] = ((3 + k) * x * 20 * (Math.PI / 180)) / (Math.PI + k * Math.abs(x));
  }
  return curve;
}

function playBrightTone(
  ctx: AudioContext,
  out: AudioNode,
  freq: number,
  endFreq: number,
  duration: number,
  startTime: number,
  gainPeak = 0.18,
  type: OscillatorType = "triangle",
) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, startTime);
  if (endFreq !== freq) {
    osc.frequency.exponentialRampToValueAtTime(
      Math.max(endFreq, 24),
      startTime + duration,
    );
  }
  gain.gain.setValueAtTime(0.001, startTime);
  gain.gain.linearRampToValueAtTime(gainPeak, startTime + 0.005);
  gain.gain.exponentialRampToValueAtTime(0.0008, startTime + duration);
  osc.connect(gain);
  gain.connect(out);
  osc.start(startTime);
  osc.stop(startTime + duration + 0.01);
}

function playCrispNoise(
  ctx: AudioContext,
  out: AudioNode,
  duration: number,
  startTime: number,
  startFreq: number,
  endFreq: number,
  gainPeak = 0.25,
  filterType: BiquadFilterType = "bandpass",
  q = 1.2,
  distort = false,
) {
  const sampleRate = ctx.sampleRate;
  const length = Math.max(1, Math.floor(sampleRate * duration));
  const buffer = ctx.createBuffer(1, length, sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < length; i++) {
    const env = Math.pow(1 - i / length, 0.55);
    data[i] = (Math.random() * 2 - 1) * env;
  }

  const src = ctx.createBufferSource();
  src.buffer = buffer;

  const filter = ctx.createBiquadFilter();
  filter.type = filterType;
  filter.Q.setValueAtTime(q, startTime);
  filter.frequency.setValueAtTime(startFreq, startTime);
  if (endFreq !== startFreq) {
    filter.frequency.exponentialRampToValueAtTime(
      Math.max(endFreq, 60),
      startTime + duration,
    );
  }

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.001, startTime);
  gain.gain.linearRampToValueAtTime(gainPeak, startTime + 0.003);
  gain.gain.exponentialRampToValueAtTime(0.001, startTime + duration);

  src.connect(filter);
  if (distort) {
    const shaper = ctx.createWaveShaper();
    shaper.curve = makeDistortionCurve(65);
    shaper.oversample = "2x";
    filter.connect(shaper);
    shaper.connect(gain);
  } else {
    filter.connect(gain);
  }
  gain.connect(out);
  src.start(startTime);
  src.stop(startTime + duration + 0.01);
}

/**
 * Crisp card-tick sound when selecting/deselecting a card in hand.
 */
export function playSelectSound(): void {
  const audio = getContext();
  if (!audio) return;
  const { ctx, out } = audio;
  const now = ctx.currentTime;
  playCrispNoise(ctx, out, 0.022, now, 4200, 2800, 0.16, "highpass", 0.9);
  playBrightTone(ctx, out, 1350, 1950, 0.022, now, 0.09, "sine");
}

/**
 * Rapid crisp card-riffle sound when dealing a new round.
 */
export function playDealSound(): void {
  const audio = getContext();
  if (!audio) return;
  const { ctx, out } = audio;
  const now = ctx.currentTime;
  for (let i = 0; i < 8; i++) {
    const t = now + i * 0.036;
    playCrispNoise(
      ctx,
      out,
      0.028,
      t,
      3400 + i * 240,
      2000,
      0.16,
      "bandpass",
      1.1,
    );
    playBrightTone(ctx, out, 900 + i * 95, 580, 0.024, t, 0.07, "triangle");
  }
}

/**
 * Dedicated fixed sound effect for "不出 / 要不起" (Pass during card play).
 * Crisp two-tone downward woodblock table-knock (E5 -> A4) so passing has its own unmistakable signature.
 */
export function playPassSound(): void {
  const audio = getContext();
  if (!audio) return;
  const { ctx, out } = audio;
  const now = ctx.currentTime;

  // First knock (table tap + E5 marimba wood tone)
  playCrispNoise(ctx, out, 0.022, now, 2600, 1400, 0.14, "bandpass", 1.6);
  playBrightTone(ctx, out, 659.25, 580, 0.06, now, 0.16, "sine");
  playBrightTone(ctx, out, 1318.5, 1100, 0.035, now, 0.05, "triangle");

  // Second lower knock (A4 marimba wood tone, "过")
  playCrispNoise(ctx, out, 0.024, now + 0.065, 2100, 1100, 0.12, "bandpass", 1.6);
  playBrightTone(ctx, out, 440, 392, 0.085, now + 0.065, 0.15, "sine");
}

/**
 * Sound effect for Call Landlord, Rob Landlord, or No Call / No Rob.
 */
export function playBidSound(
  kind: "call" | "rob" | "no_call" | "no_rob" | "pass",
): void {
  if (kind === "pass") {
    playPassSound();
    return;
  }
  const audio = getContext();
  if (!audio) return;
  const { ctx, out } = audio;
  const now = ctx.currentTime;

  if (kind === "call") {
    // Bright rising triad (G5 -> B5 -> D6)
    const notes = [783.99, 987.77, 1174.66];
    notes.forEach((f, idx) => {
      const t = now + idx * 0.065;
      playBrightTone(ctx, out, f, f, 0.16, t, 0.18, "triangle");
      playBrightTone(ctx, out, f * 2, f * 2, 0.1, t, 0.06, "sine");
    });
    return;
  }

  if (kind === "rob") {
    // Urgent high-energy 4-note brass/bell sting (A5 -> C#6 -> E6 -> A6)
    const notes = [880, 1108.73, 1318.51, 1760];
    notes.forEach((f, idx) => {
      const t = now + idx * 0.055;
      playBrightTone(ctx, out, f, f * 1.01, 0.16, t, 0.19, "sawtooth");
      playBrightTone(ctx, out, f * 1.5, f * 1.5, 0.12, t, 0.08, "triangle");
    });
    playCrispNoise(ctx, out, 0.05, now, 4500, 2200, 0.14, "highpass", 1.0);
    return;
  }

  // No call / No rob
  playPassSound();
}

/**
 * Sound effect for playing a card combination on the felt table.
 */
export function playComboSound(comboType: ComboType): void {
  const audio = getContext();
  if (!audio) return;
  const { ctx, out } = audio;
  const now = ctx.currentTime;

  if (comboType === "rocket") {
    // Stage 1: Supersonic jet/missile launch whistle (0.00s -> 0.18s)
    playBrightTone(ctx, out, 380, 2600, 0.18, now, 0.2, "sawtooth");
    playBrightTone(ctx, out, 570, 3900, 0.18, now, 0.14, "triangle");
    playCrispNoise(ctx, out, 0.18, now, 1200, 7200, 0.22, "bandpass", 1.8);

    // Stage 2: Sky-shattering twin detonation crack + broadband roar (0.17s)
    const impact = now + 0.17;
    playCrispNoise(ctx, out, 0.06, impact, 4800, 1800, 0.48, "highpass", 1.2, true);
    playCrispNoise(ctx, out, 0.55, impact, 8500, 420, 0.42, "lowpass", 2.2, true);
    playCrispNoise(ctx, out, 0.28, impact + 0.09, 5600, 900, 0.3, "bandpass", 1.1, true);

    // Punchy upper-bass + mid-range body (audible on all speakers)
    playBrightTone(ctx, out, 360, 48, 0.42, impact, 0.36, "sawtooth");
    playBrightTone(ctx, out, 220, 42, 0.45, impact, 0.34, "square");

    // Golden shockwave fanfare chord
    const fanfare = [1046.5, 1318.51, 1567.98, 2093];
    fanfare.forEach((f, i) => {
      playBrightTone(
        ctx,
        out,
        f,
        f,
        0.32,
        impact + 0.06 + i * 0.035,
        0.14,
        "sawtooth",
      );
    });
    return;
  }

  if (comboType === "bomb") {
    // Stage 1: Fast incoming whistle + fuse spark (0.00s -> 0.09s)
    playBrightTone(ctx, out, 2400, 340, 0.09, now, 0.18, "sawtooth");
    playCrispNoise(ctx, out, 0.08, now, 5200, 2400, 0.18, "bandpass", 2.0);

    // Stage 2: Sharp explosive crack + distorted broadband blast (0.08s)
    const bang = now + 0.08;
    playCrispNoise(ctx, out, 0.045, bang, 3600, 1400, 0.5, "highpass", 1.4, true);
    playCrispNoise(ctx, out, 0.46, bang, 8200, 360, 0.4, "lowpass", 2.4, true);
    playCrispNoise(ctx, out, 0.22, bang + 0.08, 4800, 1100, 0.26, "bandpass", 1.3, true);

    playBrightTone(ctx, out, 340, 52, 0.35, bang, 0.34, "sawtooth");
    playBrightTone(ctx, out, 190, 44, 0.38, bang, 0.32, "square");

    playBrightTone(ctx, out, 783.99, 783.99, 0.2, bang + 0.02, 0.14, "sawtooth");
    playBrightTone(ctx, out, 1174.66, 1174.66, 0.24, bang + 0.04, 0.14, "triangle");
    return;
  }

  if (comboType.startsWith("airplane")) {
    playCrispNoise(ctx, out, 0.24, now, 900, 5400, 0.22, "bandpass", 1.8);
    const notes = [659.25, 830.61, 987.77, 1318.51];
    notes.forEach((f, idx) => {
      const t = now + idx * 0.045;
      playBrightTone(ctx, out, f, f * 1.02, 0.16, t, 0.16, "sawtooth");
      playBrightTone(ctx, out, f * 2, f * 2, 0.1, t, 0.07, "sine");
    });
    return;
  }

  if (comboType === "straight" || comboType === "pair_straight") {
    const scale = [587.33, 659.25, 783.99, 880, 1046.5, 1174.66, 1318.51];
    scale.forEach((f, idx) => {
      const t = now + idx * 0.032;
      playBrightTone(ctx, out, f, f, 0.12, t, 0.13, "triangle");
      playBrightTone(ctx, out, f * 2, f * 2, 0.08, t, 0.06, "sine");
    });
    playCrispNoise(ctx, out, 0.16, now, 3800, 5800, 0.16, "bandpass", 1.2);
    return;
  }

  // Crisp casino poker card snap on felt
  playCrispNoise(ctx, out, 0.025, now, 4200, 2200, 0.26, "highpass", 1.1);
  playCrispNoise(ctx, out, 0.048, now + 0.008, 2600, 900, 0.24, "bandpass", 1.0);
  playBrightTone(ctx, out, 880, 290, 0.055, now, 0.18, "triangle");

  if (comboType !== "single") {
    playCrispNoise(
      ctx,
      out,
      0.035,
      now + 0.032,
      3600,
      1600,
      0.22,
      "highpass",
      1.1,
    );
    playBrightTone(ctx, out, 1174.66, 659.25, 0.075, now + 0.025, 0.14, "triangle");
  }
}

/**
 * Bright celebratory victory fanfare.
 */
export function playFinishSound(): void {
  const audio = getContext();
  if (!audio) return;
  const { ctx, out } = audio;
  const now = ctx.currentTime;
  const chord = [523.25, 659.25, 783.99, 1046.5, 1318.51, 1567.98];
  chord.forEach((freq, i) => {
    const t = now + i * 0.06;
    playBrightTone(ctx, out, freq, freq, 0.28, t, 0.17, "triangle");
    playBrightTone(ctx, out, freq * 2, freq * 2, 0.18, t, 0.07, "sine");
  });
}

files.src/style.css:
:root {
  color-scheme: dark;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(
    ellipse at 50% 44%,
    #1c4d32 0%,
    #123622 55%,
    #0a2215 88%,
    #06160d 100%
  );
  color: #f8fafc;
  overflow-x: hidden;
}

.ddz-app {
  font: 14px/1.45 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 14px 24px 18px;
  background: radial-gradient(
    ellipse at 50% 44%,
    #1c4d32 0%,
    #123622 55%,
    #0a2215 88%,
    #06160d 100%
  );
  box-shadow: inset 0 0 110px rgba(0, 0, 0, 0.62);
  user-select: none;
}

.ddz-app * {
  box-sizing: border-box;
}

.ddz-app button,
.ddz-app input,
.ddz-app select {
  font: inherit;
}

/* Top Header Bar */
.ddz-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 18px;
  margin-bottom: 10px;
  border-radius: 14px;
  background: rgba(9, 15, 12, 0.76);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(12px);
  flex-wrap: wrap;
  flex-shrink: 0;
}

.ddz-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.ddz-emblem {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  overflow: hidden;
  flex-shrink: 0;
}

.ddz-brand h1 {
  margin: 0;
  font-size: 17px;
  font-weight: 750;
  color: #f8fafc;
  letter-spacing: -0.2px;
}

.ddz-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.ddz-top-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 34px;
  padding: 0 13px;
  border-radius: 9px;
  font-size: 12.5px;
  font-weight: 600;
  color: #e2e8f0;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  cursor: pointer;
  transition: all 0.16s ease;
}

.ddz-top-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.24);
}

.ddz-top-btn.is-active {
  background: rgba(245, 158, 11, 0.18);
  border-color: rgba(251, 191, 36, 0.5);
  color: #fde68a;
}

.ddz-top-btn.is-icon {
  width: 34px;
  padding: 0;
}

.ddz-top-btn:disabled {
  opacity: 0.45;
  cursor: default;
}

.ddz-error-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  margin-bottom: 10px;
  border-radius: 10px;
  font-size: 13px;
  background: rgba(127, 29, 29, 0.55);
  color: #fecaca;
  border: 1px solid rgba(248, 113, 113, 0.45);
  flex-shrink: 0;
}

/* Full-Bleed Spacious Felt Table — Locked 3-Row Grid (Zero Vertical Jump!) */
.ddz-table {
  position: relative;
  flex: 1;
  display: grid;
  grid-template-rows: 92px minmax(360px, 1fr) 232px;
  min-height: 684px;
  padding: 6px 14px 8px;
}

/* Row 1 (92px): Top-Center Floating Hole Cards & Score Capsule */
.ddz-top-row {
  height: 92px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 5;
}

.ddz-top-capsule {
  display: flex;
  align-items: center;
  gap: 22px;
  height: 84px;
  padding: 0 26px;
  border-radius: 16px;
  background: rgba(7, 14, 10, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(10px);
}

.ddz-hole-section {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ddz-capsule-label {
  font-size: 13px;
  font-weight: 700;
  color: #94a3b8;
}

.ddz-hole-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ddz-hole-back {
  width: 48px;
  height: 66px;
  border-radius: 7px;
  background: linear-gradient(145deg, #1d4ed8 0%, #1e3a8a 100%);
  border: 1.5px solid rgba(147, 197, 253, 0.55);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.45);
  display: grid;
  place-items: center;
}

.ddz-capsule-divider {
  width: 1px;
  height: 42px;
  background: rgba(255, 255, 255, 0.14);
}

.ddz-score-section {
  display: flex;
  align-items: center;
  gap: 16px;
}

.ddz-gold-stat {
  font-size: 14px;
  font-weight: 800;
  color: #fbbf24;
  letter-spacing: 0.2px;
  white-space: nowrap;
}

/* Row 2 (Spacious Middle Arena): Left Wing + Center Stage + Right Wing */
.ddz-arena {
  position: relative;
  z-index: 4;
  display: grid;
  grid-template-columns: 248px minmax(0, 1fr) 248px;
  gap: 20px;
  min-height: 360px;
  align-items: center;
}

.ddz-wing {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  height: 310px;
  justify-content: flex-start;
  padding-top: 18px;
}

.ddz-wing.is-left {
  align-items: flex-start;
}

.ddz-wing.is-right {
  align-items: flex-end;
}

/* Speech Bubbles — Directly Above Each Player Pill (Strictly Absolute Positioned) */
.ddz-quote-bubble {
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 650;
  color: #fef3c7;
  background: rgba(15, 23, 38, 0.92);
  border: 1px solid rgba(251, 191, 36, 0.48);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.5);
  max-width: 260px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
  z-index: 15;
  animation: ddz-bubble-pop 0.2s cubic-bezier(0.2, 0.8, 0.2, 1);
}

@keyframes ddz-bubble-pop {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.ddz-quote-bubble.is-floating {
  position: absolute;
  top: -22px;
}

.ddz-quote-bubble.is-floating.is-left {
  left: 0;
}

.ddz-quote-bubble.is-floating.is-right {
  right: 0;
}

.ddz-quote-bubble.is-bottom-float {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 0;
}

/* Player Identity Badge Pill */
.ddz-player-pill {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  height: 58px;
  padding: 0 16px 0 10px;
  border-radius: 15px;
  background: rgba(15, 23, 36, 0.86);
  border: 1.5px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(8px);
  min-width: 194px;
  flex-shrink: 0;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.ddz-player-pill.is-compact {
  height: 52px;
  min-width: 180px;
  padding: 0 14px 0 10px;
}

.ddz-player-pill.is-turn {
  border-color: #fbbf24;
  box-shadow:
    0 0 0 2px rgba(251, 191, 36, 0.35),
    0 8px 24px rgba(0, 0, 0, 0.5);
}

/* Avatar with Golden Polygonal Star-Burst Frame for Landlord */
.ddz-avatar-wrap {
  position: relative;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.ddz-avatar-wrap.is-compact {
  width: 38px;
  height: 38px;
}

.ddz-landlord-star-ring {
  position: absolute;
  inset: -4px;
  width: calc(100% + 8px);
  height: calc(100% + 8px);
  filter: drop-shadow(0 0 6px rgba(251, 191, 36, 0.55));
  pointer-events: none;
}

.ddz-avatar-circle {
  position: relative;
  z-index: 2;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  overflow: hidden;
  flex-shrink: 0;
}

.ddz-avatar-wrap.is-compact .ddz-avatar-circle {
  width: 32px;
  height: 32px;
}

.ddz-avatar-circle.is-peasant {
  background: radial-gradient(circle at 30% 30%, #3b82f6, #1d4ed8);
  border: 2px solid #93c5fd;
  color: #ffffff;
}

.ddz-avatar-circle.is-landlord {
  background: #1e293b;
  border: 2px solid #fde047;
  color: #fde047;
}

.ddz-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ddz-landlord-crown-tag {
  position: absolute;
  top: -5px;
  right: -4px;
  z-index: 4;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: linear-gradient(135deg, #fde047 0%, #d97706 100%);
  border: 1.5px solid #78350f;
  color: #451a03;
  display: grid;
  place-items: center;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.45);
}

.ddz-pill-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.ddz-pill-name-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.ddz-pill-name {
  font-size: 13px;
  font-weight: 700;
  color: #f8fafc;
  max-width: 112px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ddz-mini-count {
  padding: 1px 6px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  background: rgba(255, 255, 255, 0.12);
  color: #fde68a;
}

.ddz-mini-count.is-alarm {
  background: rgba(239, 68, 68, 0.35);
  color: #fca5a5;
}

.ddz-role-pill {
  display: inline-block;
  align-self: flex-start;
  padding: 1px 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
}

.ddz-role-pill.is-peasant {
  background: rgba(37, 99, 235, 0.32);
  border: 1px solid rgba(96, 165, 250, 0.55);
  color: #93c5fd;
}

.ddz-role-pill.is-landlord {
  background: rgba(217, 119, 6, 0.35);
  border: 1px solid rgba(251, 191, 36, 0.65);
  color: #fcd34d;
}

.ddz-role-pill.is-undecided {
  background: rgba(255, 255, 255, 0.1);
  color: #cbd5e1;
}

/* Fixed-Height Side Card Fan Box (220px in both Normal & God View) */
.ddz-side-fan-box {
  position: relative;
  width: 244px;
  height: 220px;
  max-height: 220px;
  flex-shrink: 0;
}

.ddz-side-back-fan {
  position: relative;
  width: 140px;
  height: 215px;
}

.ddz-side-back-fan.is-left {
  margin-left: 16px;
}

.ddz-side-back-fan.is-right {
  margin-left: auto;
  margin-right: 16px;
}

.ddz-blue-card-back {
  position: absolute;
  top: 0;
  left: 12px;
  width: 96px;
  height: 64px;
  border-radius: 8px;
  background:
    radial-gradient(
      circle at 50% 50%,
      rgba(96, 165, 250, 0.22),
      transparent 70%
    ),
    linear-gradient(135deg, #1e40af 0%, #172554 100%);
  border: 1.5px solid rgba(96, 165, 250, 0.6);
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.55);
  display: grid;
  place-items: center;
}

.ddz-back-diamond {
  width: 12px;
  height: 12px;
  background: rgba(147, 197, 253, 0.32);
  transform: rotate(45deg);
  border-radius: 2px;
}

/* Tightly Stacked Side Cards when God View is ON */
.ddz-side-stacked-rows {
  display: flex;
  flex-direction: column;
  padding-top: 8px;
}

.ddz-side-stacked-rows.is-left {
  align-items: flex-start;
}

.ddz-side-stacked-rows.is-right {
  align-items: flex-end;
}

.ddz-side-stacked-row {
  display: flex;
  align-items: center;
}

.ddz-side-stacked-row.is-second {
  margin-top: -14px;
}

.ddz-side-stacked-row .ddz-poker-card.is-mini + .ddz-poker-card.is-mini {
  margin-left: -27px;
}

.ddz-side-stacked-row .ddz-poker-card.is-mini:not(:last-child) .ddz-card-pip {
  opacity: 0.14;
}

/* Center Stage & Absolutely Positioned Three-Directional Table Spots */
.ddz-center-felt {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 320px;
}

.ddz-center-overlay {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  width: 340px;
  padding: 24px 22px;
  border-radius: 18px;
  background: rgba(7, 14, 10, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
}

.ddz-gold-crown {
  color: #fbbf24;
}

.ddz-center-overlay h2 {
  margin: 8px 0 6px;
  font-size: 19px;
}

.ddz-center-overlay p {
  margin: 0 0 16px;
  font-size: 13px;
  color: #cbd5e1;
}

.ddz-table-spot {
  position: absolute;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.ddz-table-spot.is-left {
  top: 16%;
  left: 5%;
}

.ddz-table-spot.is-right {
  top: 16%;
  right: 5%;
}

.ddz-table-spot.is-bottom {
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
}

.ddz-table-spot.is-reigning {
  z-index: 8;
}

.ddz-table-spot.is-previous {
  z-index: 3;
  opacity: 0.82;
}

.ddz-table-played-fan {
  display: flex;
  align-items: center;
  justify-content: center;
}

.ddz-table-played-fan .ddz-poker-card + .ddz-poker-card {
  margin-left: -30px;
}

.ddz-table-played-fan.is-dense .ddz-poker-card + .ddz-poker-card {
  margin-left: -38px;
}

.ddz-combo-badge {
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  color: #fde68a;
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid rgba(251, 191, 36, 0.35);
  white-space: nowrap;
}

.ddz-table-spot.is-reigning .ddz-combo-badge {
  border-color: #fbbf24;
  box-shadow: 0 0 10px rgba(251, 191, 36, 0.35);
}

.ddz-spot-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 20px;
  border-radius: 11px;
  font-size: 14px;
  font-weight: 700;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
  white-space: nowrap;
}

.ddz-spot-chip.is-pass {
  background: rgba(8, 16, 12, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #94a3b8;
}

.ddz-spot-chip.is-gold {
  background: linear-gradient(180deg, #fbbf24 0%, #d97706 100%);
  color: #1e293b;
}

.ddz-spot-chip.is-thinking {
  font-size: 13px;
  background: rgba(245, 158, 11, 0.2);
  border: 1px solid rgba(251, 191, 36, 0.45);
  color: #fde68a;
}

.ddz-pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fbbf24;
  animation: ddz-pulse 1.2s infinite ease-in-out;
}

@keyframes ddz-pulse {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.85);
  }
  50% {
    opacity: 1;
    transform: scale(1.15);
  }
}

.ddz-winner-toast {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 20;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 24px;
  border-radius: 999px;
  background: rgba(15, 23, 36, 0.94);
  border: 1.5px solid #fbbf24;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.65);
  font-size: 15px;
  color: #fef3c7;
  white-space: nowrap;
}

.ddz-winner-mult {
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(245, 158, 11, 0.25);
  color: #fbbf24;
  font-weight: 800;
}

/* Authentic Dual-Index Poker Card Component (Rendered via CSS attr(data-label) for DOM text privacy) */
.ddz-poker-card {
  position: relative;
  border-radius: 9px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #cbd5e1;
  box-shadow: -3px 6px 14px rgba(0, 0, 0, 0.42);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 6px 7px;
  user-select: none;
  flex-shrink: 0;
}

.ddz-poker-card.is-red {
  color: #dc2626;
}

.ddz-poker-card.is-black {
  color: #0f172a;
}

.ddz-poker-card.is-hole {
  width: 48px;
  height: 66px;
  padding: 4px 5px;
  border-radius: 7px;
}

.ddz-poker-card.is-table {
  width: 68px;
  height: 96px;
  padding: 6px 7px;
  border-radius: 8px;
}

.ddz-poker-card.is-hand {
  width: 78px;
  height: 112px;
  padding: 7px 8px;
  border-radius: 10px;
  transform: translateY(var(--fan-y, 0px)) rotate(var(--fan-angle, 0deg));
  transform-origin: 50% 180%;
  transition:
    transform 0.15s cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 0.15s ease,
    border-color 0.15s ease;
}

.ddz-poker-card.is-mini {
  width: 46px;
  height: 64px;
  padding: 3px 4px;
  border-radius: 6px;
}

.ddz-poker-card.is-interactive {
  cursor: pointer;
}

.ddz-poker-card.is-hand.is-interactive:hover:not(:disabled) {
  transform: translateY(calc(var(--fan-y, 0px) - 10px))
    rotate(var(--fan-angle, 0deg));
  border-color: #f59e0b;
}

.ddz-poker-card.is-hand.is-selected {
  transform: translateY(calc(var(--fan-y, 0px) - 22px))
    rotate(var(--fan-angle, 0deg)) !important;
  background: #fffbeb;
  border: 2px solid #f59e0b;
  box-shadow:
    0 0 0 3px rgba(245, 158, 11, 0.32),
    -4px 12px 22px rgba(0, 0, 0, 0.55);
}

.ddz-card-corner {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 0.95;
  width: fit-content;
}

.ddz-card-corner.is-bottom {
  align-self: flex-end;
  transform: rotate(180deg);
}

.ddz-poker-card.is-mini .ddz-card-corner.is-bottom,
.ddz-poker-card.is-hole .ddz-card-corner.is-bottom {
  display: none;
}

.ddz-card-rank::before {
  content: attr(data-label);
}

.ddz-card-suit::before {
  content: attr(data-label);
}

.ddz-card-pip::before {
  content: attr(data-label);
}

.ddz-card-rank {
  font-size: 16px;
  font-weight: 850;
  letter-spacing: -0.6px;
}

.ddz-poker-card.is-joker .ddz-card-rank {
  font-size: 8.5px;
  letter-spacing: 0px;
}

.ddz-poker-card.is-hole .ddz-card-rank {
  font-size: 13px;
}

.ddz-poker-card.is-mini .ddz-card-rank {
  font-size: 11px;
}

.ddz-card-suit {
  font-size: 11.5px;
  margin-top: 2px;
}

.ddz-poker-card.is-hole .ddz-card-suit,
.ddz-poker-card.is-mini .ddz-card-suit {
  font-size: 9.5px;
}

.ddz-card-pip {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 27px;
  line-height: 1;
  opacity: 0.92;
  pointer-events: none;
}

.ddz-poker-card.is-hole .ddz-card-pip {
  font-size: 19px;
  top: 58%;
}

.ddz-poker-card.is-mini .ddz-card-pip {
  font-size: 15px;
  top: 62%;
}

/* Row 3 (232px): Locked 54px Control Bar + Locked 178px Hand Fan Slot */
.ddz-bottom-zone {
  position: relative;
  z-index: 6;
  display: grid;
  grid-template-rows: 54px 178px;
  height: 232px;
  max-height: 232px;
}

.ddz-bottom-hud {
  width: 100%;
  height: 54px;
  max-height: 54px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  flex-wrap: nowrap;
}

.ddz-bottom-pill-wrap {
  position: relative;
  flex-shrink: 0;
}

.ddz-action-slot {
  height: 54px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ddz-action-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: nowrap;
}

.ddz-idle-bar {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 16px;
  border-radius: 999px;
  font-size: 12.5px;
  color: rgba(255, 255, 255, 0.65);
  background: rgba(7, 14, 10, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.ddz-pill-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 38px;
  padding: 0 20px;
  border-radius: 11px;
  font-size: 13.5px;
  font-weight: 750;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.16s ease;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
}

.ddz-pill-btn:disabled {
  opacity: 0.45;
  cursor: default;
}

.ddz-pill-btn.is-pass {
  background: linear-gradient(180deg, #5c2824 0%, #431c19 100%);
  border: 1.5px solid #991b1b;
  color: #fca5a5;
}

.ddz-pill-btn.is-pass:hover:not(:disabled) {
  filter: brightness(1.12);
}

.ddz-pill-btn.is-hint {
  background: linear-gradient(180deg, #27473c 0%, #1b332b 100%);
  border: 1.5px solid #4ade80;
  color: #ecfdf5;
}

.ddz-pill-btn.is-hint:hover:not(:disabled) {
  filter: brightness(1.12);
}

.ddz-pill-btn.is-gold {
  background: linear-gradient(180deg, #fbbf24 0%, #b45309 100%);
  border: 1.5px solid #fde68a;
  color: #1e293b;
}

.ddz-pill-btn.is-gold:disabled {
  background: rgba(120, 83, 24, 0.55);
  border-color: rgba(217, 119, 6, 0.35);
  color: rgba(254, 243, 199, 0.55);
}

.ddz-pill-btn.is-gold:hover:not(:disabled) {
  filter: brightness(1.08);
}

.ddz-talk-input {
  width: 196px;
  height: 36px;
  padding: 0 12px;
  border-radius: 10px;
  font-size: 12px;
  background: rgba(7, 14, 10, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #f8fafc;
  outline: none;
}

/* Hand Fan Slot — Overflow Visible & Generous Padding so Cards Are NEVER Clipped */
.ddz-arch-fan-slot {
  position: relative;
  height: 178px;
  max-height: 178px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: visible;
}

.ddz-arch-fan {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 26px 24px 20px;
  overflow: visible;
}

.ddz-arch-fan .ddz-poker-card + .ddz-poker-card {
  margin-left: -30px;
}

.ddz-spectator-mask {
  padding: 16px 26px;
  border-radius: 14px;
  background: rgba(7, 14, 10, 0.65);
  border: 1px dashed rgba(255, 255, 255, 0.18);
  color: #94a3b8;
  font-size: 13px;
}

/* Modal & Custom Seat Selector with Model Icons */
.ddz-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.68);
  display: grid;
  place-items: center;
  z-index: 60;
  padding: 16px;
}

.ddz-modal {
  width: 100%;
  max-width: 460px;
  padding: 22px;
  border-radius: 16px;
  background: #111827;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.6);
  color: #f8fafc;
}

.ddz-modal-head h3 {
  margin: 0 0 6px;
  font-size: 18px;
}

.ddz-modal-head p {
  margin: 0 0 16px;
  font-size: 12.5px;
  color: #94a3b8;
}

.ddz-slot-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-bottom: 18px;
}

.ddz-slot-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ddz-slot-label {
  font-size: 12px;
  font-weight: 700;
  color: #cbd5e1;
}

.ddz-select-wrap {
  position: relative;
}

.ddz-select-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 10px;
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #f8fafc;
  cursor: pointer;
  transition: border-color 0.15s ease;
}

.ddz-select-trigger:hover {
  border-color: rgba(251, 191, 36, 0.55);
}

.ddz-select-item-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.ddz-select-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.ddz-select-icon.is-human {
  background: rgba(245, 158, 11, 0.22);
  color: #fbbf24;
}

.ddz-select-icon.is-bot {
  background: rgba(59, 130, 246, 0.22);
  color: #60a5fa;
}

.ddz-select-icon.is-ai {
  background: rgba(168, 85, 247, 0.22);
  color: #c084fc;
}

.ddz-select-model-img {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
}

.ddz-select-texts {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-width: 0;
}

.ddz-select-title {
  font-size: 13px;
  font-weight: 650;
  color: #f8fafc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ddz-select-sub {
  font-size: 11px;
  color: #94a3b8;
}

.ddz-select-chevron {
  color: #94a3b8;
  transition: transform 0.15s ease;
}

.ddz-select-chevron.is-open {
  transform: rotate(180deg);
}

.ddz-select-menu {
  position: absolute;
  top: calc(100% + 5px);
  left: 0;
  right: 0;
  z-index: 80;
  max-height: 220px;
  overflow-y: auto;
  padding: 5px;
  border-radius: 11px;
  background: #0f172a;
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.65);
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.ddz-select-option {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 10px;
  border-radius: 8px;
  background: transparent;
  border: none;
  color: #f8fafc;
  cursor: pointer;
  text-align: left;
}

.ddz-select-option:hover {
  background: rgba(255, 255, 255, 0.08);
}

.ddz-select-option.is-selected {
  background: rgba(245, 158, 11, 0.16);
}

.ddz-select-check {
  color: #fbbf24;
  flex-shrink: 0;
}

.ddz-slot-alert {
  padding: 8px 12px;
  margin-bottom: 14px;
  border-radius: 8px;
  font-size: 12px;
  background: rgba(127, 29, 29, 0.45);
  color: #fca5a5;
}

.ddz-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

